#include "A_sub_a.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void A_sub_a_initialize(void);
void A_sub_a_notify(microkit_channel channel);
void A_sub_a_timeTriggered(void);

volatile sb_queue_int32_t_1_t *Output_queue_1;
volatile sb_queue_int32_t_1_t *Input_queue_1;
sb_queue_int32_t_1_Recv_t Input_recv_queue;

#define PORT_FROM_MON 0

bool put_Output(const int32_t *data) {
  sb_queue_int32_t_1_enqueue((sb_queue_int32_t_1_t *) Output_queue_1, (int32_t *) data);

  return true;
}

int32_t last_Input_payload;

bool get_Input(int32_t *data) {
  sb_event_counter_t numDropped;
  int32_t fresh_data;
  bool isFresh = sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &Input_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_Input_payload = fresh_data;
  }
  *data = last_Input_payload;
  return isFresh;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) Output_queue_1);

  sb_queue_int32_t_1_Recv_init(&Input_recv_queue, (sb_queue_int32_t_1_t *) Input_queue_1);

  A_sub_a_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      A_sub_a_timeTriggered();
      break;
    default:
      A_sub_a_notify(channel);
  }
}
